import{_ as t,o as n,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"2. Fonctionnalités en un coup d'œil","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"2. Fonctionnalités en un coup d'œil","description":"Extrait de docs/notice-utilisateur.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/notice/2-fonctionnalites-en-un-coup-d-oeil.md","filePath":"documentation/notice/2-fonctionnalites-en-un-coup-d-oeil.md"}`),s={name:"documentation/notice/2-fonctionnalites-en-un-coup-d-oeil.md"};function o(a,e,d,u,c,l){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="2-fonctionnalités-en-un-coup-dœil" tabindex="-1">2. Fonctionnalités en un coup d&#39;œil <a class="header-anchor" href="#2-fonctionnalités-en-un-coup-dœil" aria-label="Permalink to &quot;2. Fonctionnalités en un coup d&#39;œil {#2-fonctionnalités-en-un-coup-dœil}&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Domaine</th><th>Ce que ça permet concrètement</th></tr></thead><tbody><tr><td><strong>Contenus et champs</strong></td><td>Créer ses propres types de contenu (actualité, fiche annuaire, événement, page de formulaire...) avec plus de 20 types de champs (texte, texte enrichi, liste répétable, lien, localisation, fichier, consentement...), sans développeur.</td></tr><tr><td><strong>Composition de page</strong></td><td>Construire une page en colonnes (pleine largeur, moitié-moitié, tiers-tiers...) en assemblant des blocs de contenu, avec des règles de mise en page vérifiées automatiquement.</td></tr><tr><td><strong>Listes et filtres</strong></td><td>Générer des pages « liste » (annuaire, actualités...) filtrables et paginées sans écrire de requête, avec recherche en français (accents et pluriels compris).</td></tr><tr><td><strong>Cycle de vie éditorial</strong></td><td>Circuit de validation (brouillon → relecture → validé → publié → dépublié), règles de publication/dépublication automatique programmables, alerte de contenu à réviser.</td></tr><tr><td><strong>Avis d&#39;utilité</strong></td><td>Un bouton « Cette page (ou ce contenu) vous a-t-elle été utile ? », activable au cas par cas sur une page ou un contenu, avec un simple compteur de réponses — sans recueillir ni adresse, ni identité, ni traceur.</td></tr><tr><td><strong>RGPD et cookies</strong></td><td>Registre des traitements, journal des accès aux données personnelles, gestionnaire de cookies avec détection des services tiers, durées de conservation paramétrables.</td></tr><tr><td><strong>Comptes et droits</strong></td><td>Comptes agents (back-office) et comptes usagers (espace personnel citoyen) totalement séparés ; cinq rôles (Administrateur, Éditeur, Auteur, Relecteur, Traducteur) ; restriction d&#39;accès à certaines pages du back-office par profil, avec héritage aux sous-pages ; authentification à deux facteurs.</td></tr><tr><td><strong>Formulaires en ligne</strong></td><td>Démarches en ligne avec page de relecture avant envoi, protection anti-robot (trois au choix, dont une qui ne contacte aucun service extérieur), notifications par e-mail, suivi de dossier pour l&#39;usager sans création de compte.</td></tr><tr><td><strong>Lettre d&#39;information</strong></td><td>Page d&#39;inscription à la lettre d&#39;information par thématique, avec confirmation obligatoire par e-mail (double clic) et désabonnement immédiat en un clic ; la mise en page de la lettre elle-même reste à mettre en place séparément.</td></tr><tr><td><strong>Recherche</strong></td><td>Moteur de recherche transverse à tout le site (pages, actualités, documents), avec suggestions de complément de saisie et synonymes propres à chaque site.</td></tr><tr><td><strong>Comptes usagers</strong></td><td>Espace personnel pour les usagers (abonnements, historique de démarches), connexion FranceConnect en option, export et suppression du compte conformes au RGPD.</td></tr><tr><td><strong>Conformité générée</strong></td><td>Déclaration d&#39;accessibilité et politique de confidentialité générées automatiquement à partir des informations réellement saisies dans l&#39;outil, plutôt que rédigées séparément et risquant de devenir fausses.</td></tr><tr><td><strong>Cartographie</strong></td><td>Affichage de contenus géolocalisés sur une carte, avec regroupement des points proches et recherche « autour de moi ».</td></tr><tr><td><strong>Multi-site</strong></td><td>Gérer plusieurs sites d&#39;une même organisation (mairie + CCAS, par exemple) avec du contenu partagé ou propre à chacun, et création de nouveaux sites à partir d&#39;un modèle.</td></tr><tr><td><strong>Tâches automatiques</strong></td><td>Un ordonnanceur livré avec le logiciel exécute seul ce qui doit l&#39;être : dépublication à la date de fin programmée, renvoi des courriels non partis, propagation entre sites, purge des brouillons abandonnés, application des durées de conservation, suppression des comptes usagers inactifs.</td></tr><tr><td><strong>Fonctions assistées par IA (optionnelles)</strong></td><td>Suggestion de texte alternatif d&#39;image (peut s&#39;appliquer automatiquement si l&#39;organisation l&#39;autorise, sinon attend une relecture), extraction de texte des documents PDF/scannés pour la recherche, réponse automatique documentée à une question, alerte de contenu qui semble dépassé, suggestion de titre/résumé pour le référencement — ces trois dernières fonctions ne s&#39;appliquent jamais sans validation humaine, quel que soit le réglage de l&#39;installation. Désactivées tant qu&#39;aucun fournisseur d&#39;IA n&#39;est configuré.</td></tr></tbody></table>',2)])])}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
